const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function menuHTML(items,mobile=false,lang='en'){const path=p=>lang==='en'?p:p.replace(/^\/satin(?=\/|$)/,'/satin/'+lang);return items.filter(m=>m.active!==false).map(m=>m.groups?.length?(mobile?`<details><summary class="${m.key==='wraps'?'wraps-nav':''}">${esc(m.label)}</summary>${m.groups.map(g=>`<div><b>${esc(g.label)}</b>${g.links.filter(l=>l.active!==false).map(l=>`<a href="${esc(path(l.href))}"${/^all\b/i.test(l.label)?' class="all-link"':''}>${esc(l.label)}</a>`).join('')}</div>`).join('')}</details>`:`<button type="button" data-mega="${esc(m.key)}" aria-expanded="false">${esc(m.label)}<svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M6 9l6 6 6-6"/></svg></button>`):`<a class="${mobile?'plain-link':'studio-nav'}" href="${esc(path(m.href))}">${esc(m.label)}</a>`).join('');}
