export function migrateNavigation(items){const rows=structuredClone(items);for(const m of rows){if(m.key==='apparel')for(const g of m.groups||[]){g.links=g.links.filter(l=>l.label!=='DTF print');for(const l of g.links)if(l.label==='DTF transfer')l.href='/satin/shop/dtf-transfers';}if(m.key==='print'){const g=m.groups.find(g=>g.label==='Large Format');if(g&&!g.links.some(l=>l.href.includes('poly-bag')))g.links.push({label:'Poly Bag Lawn Sign',href:'/satin/print-shop/large-format/poly-bag-lawn-sign',active:true});if(!m.groups.some(g=>g.links.some(l=>l.href.startsWith('/satin/print-shop/labels')))){const at=m.groups.findIndex(g=>g.label==='Help');m.groups.splice(at<0?m.groups.length:at,0,{label:'Labels & Stickers',links:[['Labels & stickers','/satin/print-shop/labels'],['Roll labels','/satin/print-shop/labels/roll-labels'],['Sticker sheets','/satin/print-shop/labels/sticker-sheets'],['Die-cut stickers','/satin/print-shop/labels/die-cut-stickers']].map(([label,href])=>({label,href,active:true}))});}}if(m.key==='shop'){const g=m.groups.find(g=>g.label==='Services');if(g)for(const [label,href] of [['Social Media','/satin/social-media-services'],['Videography','/satin/videography']])if(!g.links.some(l=>l.href===href))g.links.push({label,href,active:true});}}if(!rows.some(m=>m.key==='login'))rows.push({key:'login',label:'Log in',href:'/satin/login',active:true,groups:[]});return rows;}
DEFAULT_NAVIGATION.splice(0,DEFAULT_NAVIGATION.length,...migrateNavigation(DEFAULT_NAVIGATION));
